-- ICT371 Question 10: Scholarship Application Assessment (MySQL 8.0)
CREATE DATABASE IF NOT EXISTS ict371_q10_scholarship; USE ict371_q10_scholarship;
CREATE TABLE students(student_id INT AUTO_INCREMENT PRIMARY KEY,student_number VARCHAR(30) NOT NULL UNIQUE,full_name VARCHAR(120) NOT NULL);
CREATE TABLE applications(application_id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,age_at_application INT NOT NULL,monthly_income DECIMAL(12,2) NOT NULL,average_mark DECIMAL(5,2) NOT NULL,submitted_on DATETIME NOT NULL,status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',FOREIGN KEY(student_id) REFERENCES students(student_id),CHECK(age_at_application>0 AND monthly_income>=0 AND average_mark BETWEEN 0 AND 100));
CREATE TABLE decision_audit(audit_id BIGINT AUTO_INCREMENT PRIMARY KEY,application_id BIGINT NOT NULL,old_status ENUM('PENDING','APPROVED','REJECTED') NOT NULL,new_status ENUM('PENDING','APPROVED','REJECTED') NOT NULL,changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(application_id) REFERENCES applications(application_id));
INSERT INTO students(student_number,full_name) VALUES('S001','Leya'),('S002','Bwalya'),('S003','Chola');
DELIMITER $$
CREATE FUNCTION fn_scholarship_eligible(p_age INT,p_income DECIMAL(12,2),p_mark DECIMAL(5,2)) RETURNS BOOLEAN DETERMINISTIC NO SQL BEGIN IF p_age IS NULL OR p_income IS NULL OR p_mark IS NULL OR p_age<=0 OR p_income<0 OR p_mark<0 OR p_mark>100 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid eligibility input'; END IF; RETURN p_age BETWEEN 18 AND 25 AND p_income<=3000 AND p_mark>=70; END$$
CREATE TRIGGER trg_application_status_audit AFTER UPDATE ON applications FOR EACH ROW BEGIN IF OLD.status<>NEW.status THEN INSERT INTO decision_audit(application_id,old_status,new_status) VALUES(NEW.application_id,OLD.status,NEW.status); END IF; END$$
CREATE PROCEDURE pr_assess_application(IN p_application_id BIGINT) BEGIN DECLARE v_age INT; DECLARE v_income DECIMAL(12,2); DECLARE v_mark DECIMAL(5,2); DECLARE v_status VARCHAR(10); SELECT age_at_application,monthly_income,average_mark,status INTO v_age,v_income,v_mark,v_status FROM applications WHERE application_id=p_application_id; IF v_status IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown application'; END IF; IF v_status<>'PENDING' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Application already assessed'; END IF; UPDATE applications SET status=IF(fn_scholarship_eligible(v_age,v_income,v_mark),'APPROVED','REJECTED') WHERE application_id=p_application_id; END$$
CREATE PROCEDURE pr_assess_pending() BEGIN DECLARE done INT DEFAULT 0; DECLARE v_id BIGINT; DECLARE c CURSOR FOR SELECT application_id FROM applications WHERE status='PENDING' ORDER BY application_id; DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=1; OPEN c; assess_loop: LOOP FETCH c INTO v_id; IF done THEN LEAVE assess_loop; END IF; CALL pr_assess_application(v_id); END LOOP; CLOSE c; END$$
DELIMITER ;
INSERT INTO applications(student_id,age_at_application,monthly_income,average_mark,submitted_on,status) VALUES(1,20,2500,85,NOW(),'PENDING'),(2,17,2000,90,NOW(),'PENDING'),(3,25,3000,70,NOW(),'PENDING'),(1,26,1800,80,NOW(),'PENDING'),(2,21,3001,95,NOW(),'PENDING'),(3,22,2500,69.99,NOW(),'PENDING');
CREATE VIEW v_approved_applicants AS SELECT s.student_number,s.full_name,a.average_mark,a.status FROM applications a JOIN students s ON s.student_id=a.student_id WHERE a.status='APPROVED';
CREATE INDEX ix_applications_status_date ON applications(status,submitted_on);
EXPLAIN SELECT application_id,student_id,average_mark FROM applications WHERE status='PENDING' AND submitted_on BETWEEN '2026-01-01' AND '2026-12-31';
SET GLOBAL event_scheduler=ON; CREATE EVENT IF NOT EXISTS ev_assess_pending ON SCHEDULE EVERY 1 WEEK STARTS (TIMESTAMP(CURRENT_DATE+INTERVAL (7-DAYOFWEEK(CURRENT_DATE)+2) DAY,'08:00:00')) DO CALL pr_assess_pending();
